package local.aicenter.app;
import android.app.Activity;
import android.text.InputType;
import android.view.View;
import android.view.ViewGroup;
import android.widget.*;
import local.aicenter.core.MeasurementSystem;
import local.aicenter.core.IndividualsChart;
import local.aicenter.core.AgentRuntime;

/** Four explicit MSA models. No file or network access; journal stores only tool/status. */
final class MeasurementScreen extends LinearLayout {
 static final String[] MODES={"交叉GR&R","偏倚","线性","稳定性（I-MR）"};
 static final String[] EXAMPLES={"P1,A,1,9\nP1,A,2,11\nP1,B,1,11\nP1,B,2,13\nP2,A,1,19\nP2,A,2,21\nP2,B,1,21\nP2,B,2,23\nP3,A,1,29\nP3,A,2,31\nP3,B,1,31\nP3,B,2,33","9\n10\n11\n12\n13","10,10\n10,11\n20,21\n20,23\n30,32\n30,35","10\n11\n10\n9\n10\n11\n10"};
 MeasurementScreen(Activity activity,CenterApplication app,Runnable home,Runnable login){super(activity);setOrientation(VERTICAL);LinearLayout bar=new LinearLayout(activity);bar.addView(button(activity,"立即断开AI",()->{app.disconnect();home.run();}),new LayoutParams(0,LayoutParams.WRAP_CONTENT,1));bar.addView(button(activity,"返回AI首页",home),new LayoutParams(0,LayoutParams.WRAP_CONTENT,1));addView(bar);LinearLayout body=new LinearLayout(activity);body.setOrientation(VERTICAL);body.setPadding(dp(18),dp(10),dp(18),dp(18));body.addView(label(activity,"测量系统分析",24));body.addView(label(activity,"GR&R：每行 零件,操作员,重复编号,测量值；须完整平衡交叉且非破坏性测量。偏倚/稳定性：每行一个测量值；参数填准确参考值。线性：每行 参考值,测量值。分号也可分行；不混入表头或缺测。",15));Spinner kind=new Spinner(activity);kind.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,MODES));body.addView(kind);EditText data=new EditText(activity);data.setHint("MSA数据");data.setMinLines(5);data.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);body.addView(data);EditText parameter=new EditText(activity);parameter.setHint("GR&R公差宽度；偏倚/稳定性参考值");parameter.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);body.addView(parameter);body.addView(label(activity,"GR&R参数=USL−LSL；0表示不计算%公差。线性忽略参数。偏倚、稳定性需已知参考值。",14));CheckBox pool=new CheckBox(activity);pool.setText("GR&R交互项p≥0.05时合并到误差");pool.setChecked(true);body.addView(pool);CheckBox confirmed=new CheckBox(activity);confirmed.setText("已核对MSA设计、参考值、独立性、时间顺序及同单位");body.addView(confirmed);TextView result=label(activity,"等待MSA数据",15);body.addView(result);LinearLayout plots=new LinearLayout(activity);plots.setOrientation(VERTICAL);body.addView(plots);kind.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){confirmed.setChecked(false);plots.removeAllViews();result.setText("已切换MSA类型，请核对格式和条件。");pool.setVisibility(position==0?View.VISIBLE:View.GONE);parameter.setVisibility(position==2?View.GONE:View.VISIBLE);}});
  body.addView(button(activity,"填入MSA示例",()->{if(!app.admin.unlocked()){login.run();return;}int i=kind.getSelectedItemPosition();data.setText(EXAMPLES[i]);parameter.setText(i==0?"100":"10");confirmed.setChecked(false);plots.removeAllViews();result.setText("合成示例仅演示统计模型，不是产品接收标准。");}));
  body.addView(button(activity,"计算MSA",()->{if(!app.admin.unlocked()){login.run();return;}if(!app.stop.enabled()){result.setText("AI已断开，请回首页恢复。");return;}plots.removeAllViews();try{if(!confirmed.isChecked())throw new IllegalArgumentException("请先确认试验设计、数据顺序、同单位及适用条件");int mode=kind.getSelectedItemPosition();double ref=mode==2?0:Double.parseDouble(parameter.getText().toString().trim());if(!Double.isFinite(ref)||Math.abs(ref)>1e50)throw new IllegalArgumentException("参考值/公差超出范围");View plot=null;String report;
   if(mode==0){MeasurementSystem.Grr r=MeasurementSystem.crossed(data.getText().toString(),true,pool.isChecked(),ref);report=r.report();plot=new MeasurementPlot(activity,r);}else if(mode==1){report=MeasurementSystem.bias(data.getText().toString(),ref,true).report();}else if(mode==2){MeasurementSystem.Linearity r=MeasurementSystem.linearity(data.getText().toString(),true);report=r.report();plot=new MeasurementPlot(activity,r);}else{IndividualsChart.Result r=IndividualsChart.calculate(data.getText().toString(),true);report="稳定性 · 参考标准时间序列\n参考值="+ref+"；平均偏倚="+(r.mean-ref)+"\n"+r.report()+"\n未检验趋势与长期漂移，未合并参考标准不确定度。";plot=new IndividualsChartView(activity,r);}result.setText(report);if(plot!=null)plots.addView(plot,new LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(mode==3?420:280)));app.db.record(java.util.UUID.randomUUID().toString(),AgentRuntime.State.SUCCEEDED,"msa.analysis","computed");
   }catch(NumberFormatException e){result.setText("请输入有效参考值/公差；GR&R可填0表示不提供公差。");}catch(IllegalArgumentException e){result.setText(e.getMessage());}catch(Exception e){result.setText("分析或本地记录未完成，请核对存储。输入未上传。");plots.removeAllViews();}}));body.addView(label(activity,"不自动判定测量系统合格。GR&R：6σ研究变差、%方差贡献分别显示；负方差截0并提示。偏倚/线性仅给模型估计及t检验，不代表等效或无偏。\n公式依据：Minitab交叉GR&R方法、NIST统计手册。F/t分布：Apache Commons Statistics 1.3（Apache-2.0）。\n"+MeasurementSystem.SOURCE,13));ScrollView scroll=new ScrollView(activity);scroll.addView(body);addView(scroll,new LayoutParams(LayoutParams.MATCH_PARENT,0,1));
 }
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private static TextView label(Activity a,String s,int size){TextView t=new TextView(a);t.setText(s);t.setTextSize(size);t.setTextColor(0xff1e302c);return t;}
 private static Button button(Activity a,String s,Runnable r){Button b=new Button(a);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
}
